/// <summary>The rows of the look-up lists of the screens: key, name (English when the interface is), active.</summary>
public static partial class Lookups
{
    public static async Task<List<LookupItem>> LoadAsync(RetailDbContext db, string table, bool english) =>
        table switch
        {
            "Categories" => await db.Categories.AsNoTracking().OrderBy(x => x.CategoryName)
                .Select(x => new LookupItem(x.CategoryID, english ? (x.CategoryNameEn ?? x.CategoryName) : x.CategoryName, x.IsActive)).ToListAsync(),
            "Units" => await db.Units.AsNoTracking().OrderBy(x => x.UnitName)
                .Select(x => new LookupItem(x.UnitID, english ? (x.UnitNameEn ?? x.UnitName) : x.UnitName, x.IsActive)).ToListAsync(),
            "Suppliers" => await db.Suppliers.AsNoTracking().OrderBy(x => x.SupplierName)
                .Select(x => new LookupItem(x.SupplierID, english ? (x.SupplierNameEn ?? x.SupplierName) : x.SupplierName, x.IsActive)).ToListAsync(),
            "SalesReps" => await db.SalesReps.AsNoTracking().OrderBy(x => x.RepName)
                .Select(x => new LookupItem(x.SalesRepID, english ? (x.RepNameEn ?? x.RepName) : x.RepName, x.IsActive)).ToListAsync(),
            "PriceLists" => await db.PriceLists.AsNoTracking().OrderBy(x => x.ListName)
                .Select(x => new LookupItem(x.PriceListID, english ? (x.ListNameEn ?? x.ListName) : x.ListName, x.IsActive)).ToListAsync(),
            "Currencies" => await db.Currencies.AsNoTracking().OrderBy(x => x.CurrencyName)
                .Select(x => new LookupItem(x.CurrencyCode, x.CurrencyCode + "  " + x.CurrencyName, x.IsActive)).ToListAsync(),
            "Employees" => await db.Employees.AsNoTracking().OrderBy(x => x.EmployeeName)
                .Select(x => new LookupItem(x.EmployeeID, x.EmployeeName, x.IsActive)).ToListAsync(),
            "CostCenters" => await db.CostCenters.AsNoTracking().OrderBy(x => x.CenterName)
                .Select(x => new LookupItem(x.CostCenterID, english ? (x.CenterNameEn ?? x.CenterName) : x.CenterName, x.IsActive)).ToListAsync(),
            _ => throw new ArgumentException("No look-up for " + table),
        };
}
